// Per-sender memory: look up this phone number's last intent/session.
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

const msg = items[0].json;
const from = msg.messages[0].from;
const text = msg.messages[0].text.body;
const phoneNumberId = msg.metadata.phone_number_id;
const prior = store.sessions[from] || {};

// Build the /api/chat request body, carrying context forward when we have it.
const body = { messages: [{ role: 'user', content: text }] };
if (prior.sessionId) body.sessionId = prior.sessionId;
if (prior.intent) body.previousIntent = prior.intent;

return [{ json: { from, text, phoneNumberId, requestBody: JSON.stringify(body) } }];

// Save the conversation context returned by /api/chat for the next message.
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

const res = items[0].json; // { body, headers, statusCode } (fullResponse)
const headers = res.headers || {};
const load = $('Load Memory').first().json;

let intent = null;
const h = headers['x-search-intent'];
if (h) {
  try { intent = JSON.parse(Buffer.from(h, 'base64url').toString('utf8')); } catch (e) {}
}
const sessionId = headers['x-chat-session'] || load.sessionId || null;

store.sessions[load.from] = { intent, sessionId, updatedAt: new Date().toISOString() };

// Light cap so static data can't grow forever (keep the 500 most recent).
const keys = Object.keys(store.sessions);
if (keys.length > 500) {
  keys
    .sort((a, b) => new Date(store.sessions[a].updatedAt) - new Date(store.sessions[b].updatedAt))
    .slice(0, keys.length - 500)
    .forEach((k) => delete store.sessions[k]);
}

return [{ json: { reply: res.body, from: load.from, phoneNumberId: load.phoneNumberId } }];
